function validate([events]) {
  if (!Array.isArray(events) || events.length < 2 || events.length > 100000) return 'events needs 2 to 10^5 entries.';
  for (const event of events) {
    if (!Array.isArray(event) || event.length !== 3 || !event.every(Number.isInteger)) return 'Each event is [startTime, endTime, value] with whole numbers.';
    const [start, end, value] = event;
    if (start < 1 || end > 1000000000 || start > end) return 'Times satisfy 1 <= startTime <= endTime <= 10^9.';
    if (value < 1 || value > 1000000) return 'Each value is between 1 and 10^6.';
  }
  return null;
}

