function maxTwoEvents(events) {
  const byStart = [...events].sort((a, b) => a[0] - b[0]);
  const byEnd = [...events].sort((a, b) => a[1] - b[1]);
  let bestEnded = 0;
  let pointer = 0;
  let answer = 0;
  for (const event of byStart) {
    const start = event[0];
    const value = event[2];
    while (pointer < byEnd.length && byEnd[pointer][1] < start) {
      bestEnded = Math.max(bestEnded, byEnd[pointer][2]);
      pointer++;
    }
    answer = Math.max(answer, bestEnded + value);
  }
  return answer;
}

