  for (let i = 0; i < events.length; i++) {
    best = Math.max(best, events[i][2]);
    for (let j = 0; j < events.length; j++) {
      const first = events[i];
      const second = events[j];
      if (first[1] < second[0]) best = Math.max(best, first[2] + second[2]);
