function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const large = size === 'large';
  const n = large ? int(1500, 2000) : int(2, 8);
  const timeTop = large ? (rand() < 0.5 ? 1000000000 : 5000) : (rand() < 0.8 ? 12 : 1000000000);
  const valueTop = rand() < 0.6 ? (large ? 1000000 : 10) : 1000000;
  const maxSpan = rand() < 0.5 ? Math.max(1, Math.floor(timeTop / 10)) : timeTop;
  const events = [];
  for (let i = 0; i < n; i++) {
    const start = int(1, timeTop);
    const end = Math.min(timeTop, start + int(0, maxSpan - 1));
    events.push([start, end, int(1, valueTop)]);
  }
  return [events];
}
